#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
const int MOD = 1e9 + 7;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<string> cards(n);
    for (int i = 0; i < n; i++) {
        cin >> cards[i];
    }

    vector<int64> fact(n + 1), pow10(200, 1);
    for (int i = 1; i <= n; i++) fact[i] = fact[i-1] * i % MOD;
    for (int i = 1; i < 200; i++) pow10[i] = pow10[i-1] * 10 % MOD;

    int64 ans = 0;

    // dp_choose[k] = C(n-1, k) for current card's perspective
    vector<int64> invfact(n + 1);
    invfact[n] = 1;
    int64 f = fact[n], e = MOD - 2;
    while (e) {
        if (e & 1) invfact[n] = invfact[n] * f % MOD;
        f = f * f % MOD;
        e >>= 1;
    }
    for (int i = n; i >= 1; i--) invfact[i-1] = invfact[i] * i % MOD;

    auto nCr = [&](int N, int R) -> int64 {
        if (R < 0 || R > N) return 0;
        return fact[N] * invfact[R] % MOD * invfact[N - R] % MOD;
    };

    for (int i = 0; i < n; i++) {
        string s = cards[i];
        int len = s.size();
        int64 val = stoll(s) % MOD;
        // For each possible total length L from 1 to n
        for (int L = 1; L <= n; L++) {
            // For each position from the right: 0 .. L-1
            for (int pos = 0; pos < L; pos++) {
                // Choose other L-1 cards from n-1 others
                if (L - 1 > n - 1) continue;
                int64 ways_choose = nCr(n - 1, L - 1);
                // Permute the L-1 other cards
                int64 ways_perm = fact[L - 1];
                // Place this card's digit value at that position
                int64 contrib = val * pow10[pos] % MOD;
                contrib = contrib * ways_choose % MOD;
                contrib = contrib * ways_perm % MOD;
                ans = (ans + contrib) % MOD;
            }
        }
    }

    cout << ans % MOD << "\n";
    return 0;
}

