#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

long long modpow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<long long> val(n + 1), pw10(n + 1);
    vector<int> len(n + 1);

    for (int i = 1; i <= n; ++i) {
        string s;
        cin >> s;
        len[i] = (int)s.size();

        long long x = 0;
        for (char c : s) x = (x * 10 + (c - '0')) % MOD;
        val[i] = x;

        pw10[i] = modpow(10, len[i]);
    }

    vector<long long> fact(n + 1), invfact(n + 1), inv(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = fact[i - 1] * i % MOD;

    invfact[n] = modpow(fact[n], MOD - 2);
    for (int i = n; i >= 1; --i) invfact[i - 1] = invfact[i] * i % MOD;

    for (int i = 1; i <= n; ++i) inv[i] = fact[i - 1] * invfact[i] % MOD; // inverse of i

    // dp[k] = sum over all ordered sequences of k distinct cards:
    // product of 10^(sum of lengths of cards placed after each chosen card)
    // equivalently, recurrence:
    // new_dp[k] += old_dp[k-1]
    // new_dp[k] += old_dp[k] * 10^{len(current)}
    vector<long long> dp(n + 1, 0), ndp(n + 1, 0);
    dp[0] = 1;

    for (int i = 1; i <= n; ++i) {
        fill(ndp.begin(), ndp.end(), 0);
        for (int k = 0; k <= i - 1; ++k) {
            // do not use card i
            ndp[k] = (ndp[k] + dp[k] * pw10[i]) % MOD;
            // use card i as the last chosen among processed cards
            ndp[k + 1] = (ndp[k + 1] + dp[k]) % MOD;
        }
        dp.swap(ndp);
    }

    // Let A_t = dp[t].
    // For a fixed card i, when total chosen cards = m, and i is at position p (1-indexed),
    // number of ways to choose/order others around it contributes:
    // C(m-1, p-1) * (p-1)! * (m-p)! = (m-1)!.
    // Summing over p gives factor m!.
    //
    // More directly, total coefficient for card i over all numbers:
    // sum_{m=1..n} (n-1)!/(n-m)! * (1/m) * A_{m-1}
    //
    // Hence answer = (sum val[i]) * sum_{t=0..n-1} (n-1-t)!? simplified below:
    // coefficient C_t = P(n-1, t) * inv[t+1] * A_t, where t = m-1.
    long long sumVals = 0;
    for (int i = 1; i <= n; ++i) {
        sumVals += val[i];
        if (sumVals >= MOD) sumVals -= MOD;
    }

    long long coef = 0;
    for (int t = 0; t <= n - 1; ++t) {
        // P(n-1, t) = (n-1)! / (n-1-t)!
        long long perm = fact[n - 1] * invfact[n - 1 - t] % MOD;
        long long add = perm * inv[t + 1] % MOD * dp[t] % MOD;
        coef += add;
        if (coef >= MOD) coef -= MOD;
    }

    long long ans = sumVals * coef % MOD;
    cout << ans % MOD << '\n';
    return 0;
}

import java.util.Scanner;

public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        sc.nextLine();
        String[] cards = new String[n];
        for (int i = 0; i < n; i++) {
            cards[i] = sc.nextLine().trim();
        }

        // Precompute factorials and inverse factorials
        long[] fact = new long[n + 1];
        long[] invFact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[n] = modPow(fact[n], MOD - 2);
        for (int i = n - 1; i >= 0; i--) {
            invFact[i] = invFact[i + 1] * (i + 1) % MOD;
        }

        long[] pow10 = new long[15]; // max digits per card is small
        pow10[0] = 1;
        for (int i = 1; i < 15; i++) {
            pow10[i] = pow10[i - 1] * 10 % MOD;
        }

        long total = 0;

        // For each subset size k (1..n)
        for (int k = 1; k <= n; k++) {
            long ways = fact[k - 1] * comb(n - 1, k - 1, fact, invFact) % MOD;
            long placeSum = 0;
            // sum of place values for positions 0..k-1
            for (int pos = 0; pos < k; pos++) {
                placeSum = (placeSum + pow10[pos]) % MOD;
            }
            long contributionPerCard = ways * placeSum % MOD;

            long digitSum = 0;
            for (String s : cards) {
                long val = Long.parseLong(s) % MOD;
                digitSum = (digitSum + val) % MOD;
            }
            total = (total + digitSum * contributionPerCard) % MOD;
        }

        System.out.println(total);
    }

    static long modPow(long a, long e) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = res * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return res;
    }

    static long comb(int n, int r, long[] fact, long[] invFact) {
        if (r < 0 || r > n) return 0;
        return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
    }
}

