        long[] g = new long[n+1];
        for(int m=0;m<=n;m++){long s=0,f=1;for(int k=0;k<=m;k++){if(k>0)f=f*(m-k+1)%MOD;s=(s+f)%MOD;}g[m]=s;}
        // fact
        long[] fact=new long[n+1];fact[0]=1;for(int i=1;i<=n;i++)fact[i]=fact[i-1]*i%MOD;
