        for(int i=0;i<n;i++){
            // dp without card i
            long[] dp=new long[n];dp[0]=1;
            for(int j=0;j<n;j++){if(j==i)continue;
                for(int k=Math.min(n-1,n);k>=1;k--)dp[k]=(dp[k]+dp[k-1]%MOD*pw[j])%MOD;}
            long contrib=0;
            for(int k=0;k<n;k++) contrib=(contrib+dp[k]%MOD*fact[k]%MOD*g[n-1-k])%MOD;
            ans=(ans+v[i]*contrib)%MOD;
        }
        System.out.println(ans);
    }
