}

import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();

        long[] val = new long[n];
        int[] len = new int[n];

        long sumA = 0;   // sum of card values
        long sumL = 0;   // sum of lengths
        int maxLen = 0;

        for (int i = 0; i < n; i++) {
            String s = fs.next();
            len[i] = s.length();
            maxLen = Math.max(maxLen, len[i]);

            long x = 0;
            for (int j = 0; j < s.length(); j++) {
                x = (x * 10 + (s.charAt(j) - '0')) % MOD;
            }
            val[i] = x;
            sumA += x;
            if (sumA >= MOD) sumA -= MOD;
            sumL += len[i];
            if (sumL >= MOD) sumL -= MOD;
        }

        // factorials and inverse factorials up to n
        long[] fact = new long[n + 1];
        long[] invFact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % MOD;
        invFact[n] = modPow(fact[n], MOD - 2);
        for (int i = n; i >= 1; i--) invFact[i - 1] = invFact[i] * i % MOD;

        // powers of 10
        long[] pow10 = new long[maxLen + 1];
        pow10[0] = 1;
        for (int i = 1; i <= maxLen; i++) pow10[i] = pow10[i - 1] * 10 % MOD;

        // S[m] = sum over ordered subsets T of size m of 10^(sum lengths in T)
        // DP by elementary symmetric sums of x_i = 10^(len_i)
        long[] dp = new long[n + 1];
        dp[0] = 1;
        for (int i = 0; i < n; i++) {
            long x = pow10[len[i]];
            for (int j = i + 1; j >= 1; j--) {
                dp[j] += dp[j - 1] * x % MOD;
                if (dp[j] >= MOD) dp[j] -= MOD;
            }
        }

        long[] S = new long[n]; // only need 0..n-1
        for (int m = 0; m <= n - 1; m++) {
            S[m] = fact[m] * dp[m] % MOD;
        }

        // T = sum over all subsets U of remaining cards:
        // |U|! * (n-1-|U|)! * 10^(sum lengths in U)
        long T = 0;
        for (int m = 0; m <= n - 1; m++) {
            long ways = fact[m] * fact[n - 1 - m] % MOD;
            T = (T + ways * dp[m]) % MOD;
        }

        // For each card i, contribution:
        // a_i * [ sum over all permutations/subsets where i is included of 10^(total length after i) ]
        // This equals:
        // a_i * [ T - len_i * (n-1)!/2 ]? No.
        //
        // Derivation:
        // For fixed i and subset U of others placed after i of size m,
        // number of ways to choose/order before+after is m! * (n-1-m)!,
        // multiplier is 10^(sum len(U)).
        // Summing over all U:
        // C_i = sum_U m!(n-1-m)! 10^(sum len(U))
        //
        // This depends on excluding i from the universe. We compute:
        // C_i = sum_m m!(n-1-m)! * coeff_m over cards except i
        //
        // Let F_i(z) = product_{j!=i}(1 + x_j z), x_j=10^len_j.
        // coeff_m(F_i) = dpExcl_i[m].
        //
        // Since lengths are small enough only via x_i, we can compute exclusion by recurrence:
        // dpAll = (1 + x_i z) * dpExcl_i
        // => dpExcl_i[0]=1
        //    dpExcl_i[m] = dpAll[m] - x_i * dpExcl_i[m-1]
        //
        // Then C_i in O(n). Total O(n^2), acceptable for moderate n.
        //
        // We then exploit that cards with same length have same x_i, but values differ.
        // However constraints are unknown, so implement O(n^2) safe if n is not huge.
        //
        // To improve, group by length.
        Map<Integer, List<Integer>> byLen = new HashMap<>();
        for (int i = 0; i < n; i++) {
            byLen.computeIfAbsent(len[i], k -> new ArrayList<>()).add(i);
        }

        long answer = 0;

        // Precompute weight[m] = m!(n-1-m)!
        long[] weight = new long[n];
        for (int m = 0; m <= n - 1; m++) {
            weight[m] = fact[m] * fact[n - 1 - m] % MOD;
        }

        // Process each distinct length once
        Map<Integer, Long> coeffByLen = new HashMap<>();

        for (int L : byLen.keySet()) {
            long x = pow10[L];
            long[] excl = new long[n];
            excl[0] = 1;
            for (int m = 1; m <= n - 1; m++) {
                excl[m] = dp[m] - x * excl[m - 1] % MOD;
                if (excl[m] < 0) excl[m] += MOD;
            }

            long c = 0;
            for (int m = 0; m <= n - 1; m++) {
                c = (c + weight[m] * excl[m]) % MOD;
            }
            coeffByLen.put(L, c);
        }

        for (int i = 0; i < n; i++) {
            answer = (answer + val[i] * coeffByLen.get(len[i])) % MOD;
        }

        System.out.println(answer % MOD);
    }

    static long modPow(long a, long e) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }
}

#include <stdio.h>
#include <string.h>
#define MOD 1000000007

typedef long long ll;

int main() {
    int n;
    scanf("%d", &n);
    char cards[n][12];
    int len[n];
    ll pow10[1000];
    pow10[0] = 1;
    for (int i = 1; i < 1000; i++) 
        pow10[i] = (pow10[i-1] * 10) % MOD;

    for (int i = 0; i < n; i++) {
        scanf("%s", cards[i]);
        len[i] = strlen(cards[i]);
    }

    ll total = 0;
    // We'll use DP over subsets (2^n up to maybe 15, but n can be larger)
    // For larger n we need smarter approach: contributions based on combinatorial counts.

    // For each card, compute its value and contribution factor.
    ll val[n];
    for (int i = 0; i < n; i++) {
        val[i] = 0;
        for (int j = 0; j < len[i]; j++) {
            val[i] = (val[i] * 10 + (cards[i][j] - '0')) % MOD;
        }
    }

    // Precompute factorials
    ll fact[20];
    fact[0] = 1;
    for (int i = 1; i <= n; i++) fact[i] = (fact[i-1] * i) % MOD;

    // For each subset, each permutation: sum contributions
    // Use inclusion: For each card, consider each position in the concatenated number
    // and count how many times it appears there.

    // We'll do DP over subsets to compute sum and count
    int total_subsets = 1 << n;
    ll sum[total_subsets], cnt[total_subsets], total_len[total_subsets];
    sum[0] = 0; cnt[0] = 1; total_len[0] = 0;

    for (int mask = 1; mask < total_subsets; mask++) {
        int lsb = mask & -mask;
        int idx = __builtin_ctz(lsb);
        int prev = mask ^ lsb;
        total_len[mask] = total_len[prev] + len[idx];

        ll add_val = (val[idx] * pow10[total_len[prev]]) % MOD;
        sum[mask] = (sum[prev] + add_val * cnt[prev]) % MOD;
        cnt[mask] = cnt[prev];

        // Now combine with other previous subsets to account for permutations
        // Actually we need all permutations, so we need to sum over all ways to insert card into any position
        // Better: Use DP that builds permutations directly.
    }

    // The above DP only builds in fixed order. Need permutation handling.
    // Proper method: DP over subsets storing sum of all permutations
    // dp_sum[mask] = sum of all numbers formed by permutations of cards in mask
    // dp_cnt[mask] = number of permutations of cards in mask
    // Transition: Add a new card k not in mask at the end:
    // new_sum = dp_sum[mask] * 10^{len[k]} * dp_cnt[mask]? No, that's wrong, because each existing number gets digits appended.
    // Actually: For each permutation of mask, we append card k, so:
    // new_sum = sum_{perm in mask} (perm * 10^{len[k]} + val[k])
    // = (sum_{perm in mask} perm) * 10^{len[k]} + val[k] * cnt(mask)
    // So: dp_sum[mask|1<<k] += dp_sum[mask] * pow10[len[k]] + val[k] * dp_cnt[mask]

    ll dp_sum[1<<n], dp_cnt[1<<n];
    dp_sum[0] = 0; dp_cnt[0] = 1;
    for (int mask = 1; mask < (1<<n); mask++) {
        dp_sum[mask] = 0;
        dp_cnt[mask] = 0;
        for (int k = 0; k < n; k++) {
            if (mask & (1<<k)) {
                int prev = mask ^ (1<<k);
                ll add = (dp_sum[prev] * pow10[len[k]] + val[k] * dp_cnt[prev]) % MOD;
                dp_sum[mask] = (dp_sum[mask] + add) % MOD;
                dp_cnt[mask] = (dp_cnt[mask] + dp_cnt[prev]) % MOD;
            }
        }
    }

    ll ans = 0;
    for (int mask = 1; mask < (1<<n); mask++) {
        ans = (ans + dp_sum[mask]) % MOD;
    }

    printf("%lld\n", ans);
    return 0;
}

