typedef long long ll;
int main(){
    int n; scanf("%d",&n);
    char cards[205][205];
    ll val[205],len[205];
    for(int i=0;i<n;i++){scanf("%s",cards[i]);len[i]=strlen(cards[i]);val[i]=0;for(int j=0;j<len[i];j++)val[i]=(val[i]*10+(cards[i][j]-'0'))%MOD;}
    // For each card i, contribution = val[i] * A * B where
    // A = sum over T subset of others: |T|! * prod_{j in T} 10^len[j]
    // B_T = sum over U subset of others\T: |U|!
    // But A*B isn't separable due to disjointness.
    // DP: dp[j] = (sum_T |T|!*P(T)) and dp2[j]= sum_U |U|! over subsets of first j others
    // Since T and U disjoint, use DP with states (a,b) = (|T|,|U|) and track product.
    // dp[j][a][b] but n up to 200, too large.
    // Alternative: for each other card j, it contributes factor (1 + x*10^len[j] + y) where x marks T-membership, y marks U-membership.
    // Sum = sum_{a,b} a!*b! * [x^a y^b] product_j(1+x*10^len[j]+y)
    // = sum_{a,b} a!*b! * coeff
    // Let f(j) = sum_{a,b} a!*b! * coeff after j cards, tracked as 2D array dp[a][b]
    // n-1 up to 199, so a+b <= 199, dp is 200x200 = 40000 entries. Feasible!
    ll ans=0;
    ll pw10[205];pw10[0]=1;for(int i=1;i<=200;i++)pw10[i]=pw10[i-1]*10%MOD;
    ll fact[205];fact[0]=1;for(int i=1;i<=200;i++)fact[i]=fact[i-1]*i%MOD;
    for(int i=0;i<n;i++){
        // collect others
        // dp[a][b] = sum over subsets with |T|=a,|U|=b of P(T)
        static ll dp[205][205];
        memset(dp,0,sizeof(dp));
        dp[0][0]=1;
        for(int j=0;j<n;j++){
            if(j==i)continue;
            ll p=pw10[len[j]];
            // process in reverse
            for(int a=n;a>=0;a--)for(int b=n;b>=0;b--){
                if(!dp[a][b])continue;
                // add to T: dp[a+1][b] += dp[a][b]*p
                if(a+b+1<n)dp[a+1][b]=(dp[a+1][b]+dp[a][b]*p)%MOD;
                // add to U: dp[a][b+1] += dp[a][b]
                if(a+b+1<n)dp[a][b+1]=(dp[a][b+1]+dp[a][b])%MOD;
            }
        }
        ll contrib=0;
        for(int a=0;a<n;a++)for(int b=0;b<n;b++){
            if(!dp[a][b])continue;
            contrib=(contrib+dp[a][b]%MOD*fact[a]%MOD*fact[b])%MOD;
        }
        ans=(ans+val[i]*contrib)%MOD;
    }
    printf("%lld\n",ans);
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MOD 1000000007LL

static long long mod_pow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    char **s = (char **)malloc(n * sizeof(char *));
    int *len = (int *)malloc(n * sizeof(int));
    long long *val = (long long *)malloc(n * sizeof(long long));

    long long totalLen = 0;
    for (int i = 0; i < n; i++) {
        char buf[1000005];
        scanf("%s", buf);
        int L = (int)strlen(buf);
        s[i] = (char *)malloc((L + 1) * sizeof(char));
        strcpy(s[i], buf);
        len[i] = L;
        totalLen += L;

        long long x = 0;
        for (int j = 0; j < L; j++) {
            x = (x * 10 + (buf[j] - '0')) % MOD;
        }
        val[i] = x;
    }

    /* Precompute:
       A = sum over all subsets T of cards except i, and all orders of T,
           of 10^(sumLen(T))
       This is same for every i.

       Let dp[k][l] = sum over subsets of size k with total length l of product? No.
       Better:
       For each card length d, when included, contributes factor x * 10^d in EGF.
       Since cards are distinct and order count of a chosen set of size k is k!,
       total contribution needed for a fixed i:
         sum_{T subset others} |T|! * 10^(sumLen(T))
       and then placements around i multiply by (|T|+1)! overall:
         For chosen T with m cards, across all permutations of T plus choosing position of i,
         card i appears with coefficient (m+1)! * 10^(suffix length after i).
       Summing suffix choices gives:
         m! * sum_{U subset T} |U|! (m-|U|)! * 10^(sumLen(U))
       Hard directly.

       Instead derive by linearity over positions:
       For fixed i and fixed subset T of size m, in all (m+1)! permutations of T∪{i},
       for each split T = A ∪ B where A before i, B after i:
         number of permutations = |A|! |B|!
         contribution = val[i] * 10^(sumLen(B))
       So total for this T:
         val[i] * sum_{B subset T} |B|! (m-|B|)! 10^(sumLen(B))

       Now sum over all T subset others.
       Reindex by choosing B directly and letting A be any subset of remaining others:
         For fixed B of size b, if among remaining n-1-b cards choose any A of size a,
         coefficient = b! a! 10^(sumLen(B)).
       Therefore total coefficient for i:
         sum_{B subset others} 10^(sumLen(B)) |B|! * sum_{a=0}^{rem} C(rem, a) a!
       where rem = n-1-|B| over actual distinct remaining cards.
       But sum over subsets A of remaining of size a weighted a! equals P(rem, a) summed,
       = rem! * sum_{t=0}^{rem} 1/t! where t = rem-a.

       So coefficient depends only on B size and lengths.
    */

    /* Precompute inv factorials and coeff g[r] = sum_{a=0}^r P(r,a) = r! * sum_{t=0}^r 1/t! */
    long long *fact = (long long *)malloc((n + 1) * sizeof(long long));
    long long *invfact = (long long *)malloc((n + 1) * sizeof(long long));
    fact[0] = 1;
    for (int i = 1; i <= n; i++) fact[i] = fact[i - 1] * i % MOD;
    invfact[n] = mod_pow(fact[n], MOD - 2);
    for (int i = n; i > 0; i--) invfact[i - 1] = invfact[i] * i % MOD;

    long long *g = (long long *)malloc((n + 1) * sizeof(long long));
    long long pref = 0;
    for (int r = 0; r <= n; r++) {
        pref = (pref + invfact[r]) % MOD;
        g[r] = fact[r] * pref % MOD;
    }

    /* Need for each card i:
       coeff_i = sum_{B subset others} 10^(sumLen(B)) * |B|! * g[n-1-|B|]

       Let F_i[b] = sum over subsets B of others with size b of 10^(sumLen(B)).
       Then coeff_i = sum_b F_i[b] * b! * g[n-1-b].

       Compute global polynomial P(x)=prod_j (1 + x * 10^{len_j})
       coefficient of x^b is sum over subsets size b of 10^(sumLen).
       For each i, divide by (1 + x * 10^{len_i}) to exclude i.
       Since only length matters, group by length.
    */

    int maxL = 0;
    for (int i = 0; i < n; i++) if (len[i] > maxL) maxL = len[i];

    int *cnt = (int *)calloc(maxL + 1, sizeof(int));
    for (int i = 0; i < n; i++) cnt[len[i]]++;

    long long *pow10 = (long long *)malloc((maxL + 1) * sizeof(long long));
    pow10[0] = 1;
    for (int i = 1; i <= maxL; i++) pow10[i] = pow10[i - 1] * 10 % MOD;

    long long *P = (long long *)calloc(n + 1, sizeof(long long));
    P[0] = 1;
    int built = 0;
    for (int d = 1; d <= maxL; d++) if (cnt[d] > 0) {
        long long w = pow10[d];
        for (int t = 0; t < cnt[d]; t++) {
            for (int k = built; k >= 0; k--) {
                P[k + 1] = (P[k + 1] + P[k] * w) % MOD;
            }
            built++;
        }
    }

    /* For each distinct length d, compute Q_d = P / (1 + x*10^d)
       recurrence:
         Q[0]=P[0]
         Q[k]=P[k]-w*Q[k-1]
    */
    long long *answerByLen = (long long *)calloc(maxL + 1, sizeof(long long));
    long long *Q = (long long *)calloc(n + 1, sizeof(long long));

    for (int d = 1; d <= maxL; d++) if (cnt[d] > 0) {
        long long w = pow10[d];
        Q[0] = P[0];
        for (int k = 1; k <= n - 1; k++) {
            Q[k] = (P[k] - w * Q[k - 1]) % MOD;
            if (Q[k] < 0) Q[k] += MOD;
        }
        long long coeff = 0;
        for (int b = 0; b <= n - 1; b++) {
            coeff = (coeff + Q[b] * fact[b] % MOD * g[n - 1 - b]) % MOD;
        }
        answerByLen[d] = coeff;
    }

    long long ans = 0;
    for (int i = 0; i < n; i++) {
        ans = (ans + val[i] * answerByLen[len[i]]) % MOD;
    }

    printf("%lld\n", ans);

    for (int i = 0; i < n; i++) free(s[i]);
    free(s);
    free(len);
    free(val);
    free(fact);
    free(invfact);
    free(g);
    free(cnt);
    free(pow10);
    free(P);
    free(Q);
    free(answerByLen);

    return 0;
}

MOD = 1_000_000_007

def modinv(x):
    return pow(x, MOD - 2, MOD)

def solve():
    import sys
    input_data = sys.stdin.read().strip().split()
    if not input_data:
        return
    n = int(input_data[0])
    cards = list(map(int, input_data[1:1+n]))

    # Precompute factorials and inverse factorials
    fact = [1] * (n + 1)
    invfact = [1] * (n + 1)
    for i in range(1, n+1):
        fact[i] = fact[i-1] * i % MOD
    invfact[n] = modinv(fact[n])
    for i in range(n-1, -1, -1):
        invfact[i] = invfact[i+1] * (i+1) % MOD

    def comb(a, b):
        if b < 0 or b > a:
            return 0
        return fact[a] * invfact[b] % MOD * invfact[a-b] % MOD

    # Precompute powers of 10
    pow10 = [1] * (n + 1)
    for i in range(1, n+1):
        pow10[i] = pow10[i-1] * 10 % MOD

    # Precompute sum_pow10[m] = sum_{k=0}^{m-1} 10^k = (10^m - 1)/9 mod MOD
    sum_pow10 = [0] * (n + 1)
    inv9 = modinv(9)
    for m in range(1, n+1):
        sum_pow10[m] = (pow10[m] - 1) * inv9 % MOD

    total = 0
    for val in cards:
        for m in range(1, n+1):
            ways = comb(n-1, m-1)  # choose other cards
            contrib = val % MOD
            contrib = contrib * sum_pow10[m] % MOD
            contrib = contrib * fact[m-1] % MOD
            contrib = contrib * ways % MOD
            total = (total + contrib) % MOD

    print(total)

if __name__ == "__main__":
    solve()
